import torch
from torch.utils.data import DataLoader, Dataset

class SquareDataset(Dataset):
    def __init__(self, n):
        self.n = n

    def __len__(self):
        return self.n

    def __getitem__(self, i):
        x = torch.tensor([float(i)])
        return x, x ** 2

ds = SquareDataset(5)
print(len(ds), ds[3])
for xb, yb in DataLoader(ds, batch_size=2):
    print(xb.flatten().tolist(), yb.flatten().tolist())

